async function main() {
  console.log(`Creating ${members.length} auth users...`);

  let created = 0;
  let skipped = 0;
  let errors = 0;

  for (const member of members) {
    const { data, error } = await supabase.auth.admin.createUser({
      email: member.email,
      password: DEFAULT_PASSWORD,
      email_confirm: true,
      user_metadata: {
        full_name: member.fullName,
        employee_number: member.employeeNumber,
      },
    });

    if (error) {
      if (error.message.includes("already been registered")) {
        skipped++;
      } else {
        console.error(`  ERROR [${member.email}]: ${error.message}`);
        errors++;
      }
    } else {
      created++;
    }

    // Small delay to avoid rate limits
    if (created % 50 === 0 && created > 0) {
      console.log(`  ... processed ${created + skipped + errors} / ${members.length}`);
    }
    await new Promise((r) => setTimeout(r, 50));
  }

  console.log(`\nDone!`);
  console.log(`  Created: ${created}`);
  console.log(`  Skipped (already exist): ${skipped}`);
  console.log(`  Errors:  ${errors}`);
}

main().catch(console.error);
